import json
import itertools
import numpy as np
from sympy import symbols, SOPform, And, Or, Not, true, false

spec = TASK["public"]["specification"]
X = spec["inputs"]
y = list(map(int, spec["outputs"]))
xs = symbols("x0:10")

# Exact Boolean minimization of the public specification.
choices = []
for label in (0, 1):
    expr = SOPform(xs, [row for row, value in zip(X, y) if value == label])
    terms = [] if expr == false else list(expr.args) if expr.func == Or else [expr]
    choices.append((len(terms), label, terms))
count, label, terms = min(choices, key=lambda item: item[0])
assert count <= 34

A = {}
for i in range(4):
    A[f"w{i}"] = np.zeros((34, 10 if i == 0 else 34), dtype=np.float32)
    A[f"b{i}"] = np.zeros(34, dtype=np.float32)
A["out"] = np.zeros((3, 34), dtype=np.float32)
A["bias"] = np.array([0, 0, -1], dtype=np.float32)

cubes = []
for j, term in enumerate(terms):
    literals = [] if term == true else list(term.args) if term.func == And else [term]
    cube = {}
    for literal in literals:
        negated = literal.func == Not
        variable = literal.args[0] if negated else literal
        index = xs.index(variable)
        cube[index] = 0 if negated else 1
        A["w0"][j, index] = -1 if negated else 1
    A["b0"][j] = 1 - sum(cube.values())
    cubes.append(cube)
    for i in range(1, 4):
        A[f"w{i}"][j, j] = 1

# Verify Boolean cubes only; do not evaluate any network.
for row, expected in zip(X, y):
    covered = any(all(row[k] == v for k, v in cube.items()) for cube in cubes)
    assert (label if covered else 1 - label) == expected

A["out"][1, :count] = 1 if label == 1 else -1
A["bias"][1] = -0.5 if label == 1 else 0.5

