def accepted(sub):
    try:
        result = check_submission(sub)
    except Exception:
        return False
    if result is False:
        return False
    if isinstance(result, dict):
        if any(result.get(k) is False for k in ("ok", "valid", "success")):
            return False
        if result.get("error") or result.get("errors") or result.get("isError"):
            return False
    if isinstance(result, str):
        try:
            result = json.loads(result)
        except ValueError:
            return result.strip().lower() in ("ok", "valid", "success")
        if isinstance(result, dict):
            return not (
                any(result.get(k) is False for k in ("ok", "valid", "success"))
                or result.get("error") or result.get("errors")
            )
    return True

def candidates():
    for op in ("set", "set_tensor", "replace"):
        for field in ("values", "value"):
            for flat in (False, True):
                yield {"patch": [
                    {"op": op, "tensor": name,
                     field: (array.ravel() if flat else array).tolist()}
                    for name, array in A.items()
                ]}
    for field in ("index", "indices"):
        for flat in (False, True):
            patch = []
            for name, array in A.items():
                for index in np.ndindex(array.shape):
                    value = float(array[index])
                    if value:
                        location = int(np.ravel_multi_index(index, array.shape)) if flat else list(index)
                        patch.append({"op": "set", "tensor": name,
                                      field: location, "value": value})
            yield {"patch": patch}

for sub in candidates():
    if accepted(sub):
        with open("/work/submission.json", "w") as f:
            json.dump(sub, f, separators=(",", ":"), allow_nan=False)
        break
else:
    raise RuntimeError("No supported numeric-patch encoding found.")
